#include <cmath>
#include <iostream>
#include <memory>
#include <numbers>
#include <print>
#include <string>

class Shape {
public:
    virtual ~Shape() = default;
    virtual double area() const = 0;
    virtual std::string name() const = 0;
};

class Circle final : public Shape {
public:
    explicit Circle(double r) : r_(r) {}
    double area() const override {
        return std::numbers::pi * r_ * r_;
    }
    std::string name() const override {
        return "круг";
    }

private:
    double r_;
};

class Rect final : public Shape {
public:
    Rect(double w, double h) : w_(w), h_(h) {}
    double area() const override {
        return w_ * h_;
    }
    std::string name() const override {
        return "прямоугольник";
    }

private:
    double w_;
    double h_;
};

class Square final : public Shape {
public:
    explicit Square(double s) : s_(s) {}
    double area() const override {
        return s_ * s_;
    }
    std::string name() const override {
        return "квадрат";
    }

private:
    double s_;
};

class Triangle final : public Shape {
public:
    Triangle(double a, double b, double c) : a_(a), b_(b), c_(c) {}
    double area() const override {
        double p = (a_ + b_ + c_) / 2;
        return std::sqrt(p * (p - a_) * (p - b_) * (p - c_));
    }
    std::string name() const override {
        return "треугольник";
    }

private:
    double a_;
    double b_;
    double c_;
};

std::unique_ptr<Shape> read_shape(std::istream &in) {
    std::string kind;
    if (!(in >> kind)) {
        return nullptr;
    }
    if (kind == "circle") {
        double r;
        in >> r;
        return std::make_unique<Circle>(r);
    }
    if (kind == "rect") {
        double w, h;
        in >> w >> h;
        return std::make_unique<Rect>(w, h);
    }
    if (kind == "square") {
        double s;
        in >> s;
        return std::make_unique<Square>(s);
    }
    double a, b, c;
    in >> a >> b >> c;
    return std::make_unique<Triangle>(a, b, c);
}

int main() {
    int count = 0;
    while (auto shape = read_shape(std::cin)) {
        std::println("{}: {:.2f}", shape->name(), shape->area());
        count++;
    }
    std::println("фигур {}", count);
    return 0;
}

